for (const task of CONTENT_TASKS) {
  await test_verifyInsertRemoveCSS(
    createExtensionFn,
    {
      manifest_version: 2,
      permissions: ["*://mochi.test/*", "scripting"],
    },
    {
      tabConfig: task,
      url: CONTENT_PAGE,
      values: CONTENT_VALUES,
    }
  );
  await test_verifyInsertRemoveCSS(
    createExtensionFn,
    {
      manifest_version: 3,
      permissions: ["scripting"],
      host_permissions: ["*://mochi.test/*"],
    },
    {
      tabConfig: task,
      url: CONTENT_PAGE,
      values: CONTENT_VALUES,
    }
  );
}
